scwin.onEnter = async function () {
    /* sdd-asis-lifecycle:begin onEnter — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.search();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.content
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formVer
 * @returns
 * @hidden N
*/
scwin.content = async function (formCd, formVer) {
    /* sdd-asis-lifecycle:begin fn_Content — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ContentReq').set('formCd', formCd);
    $c.util.getComponent('dma_ContentReq').set('formVer', formVer);
    $c.util.getComponent("dma_ContentReq").set("method", "findForm");
    scwin.form_listForm.action = "/filing/findForm.do";
    await scwin.tx_fn_Content();
    /* sdd-asis-lifecycle:end */
};


