    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "fssFormPop", popupName: "fssFormPop" }, {});
