/**
 * @method
 * @name scwin.xfmUpdate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.xfmUpdate = async function () {
    /* sdd-asis-lifecycle:begin fn_XfmUpdate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("서식양식일괄업데이트를 하시겠습니까?");
    if (!_confirm) {
        return;
    }
    const _url = "/filing/form/multiFile_Load.jsp";
    const _props = "toolbar=no,menubar=no,scrollbars=no,status=yes,resizable=no,width=450,height=300";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "multiFile_Load", popupName: "multiFile_Load", width: "450", height: "300" }, {});
    /* sdd-asis-lifecycle:end */
};
